-- SQL_t02_insight_injector_repair_at_source.sql — webdesign.co.uk
--
-- Repair #1 (insight-injector) was SHIPPED BUT NOT FIXED AT SOURCE, and this
-- file closes that gap. Recording the miss plainly, because it is the useful
-- part:
--
--   * the repaired markup went to the gqls/sites repo (commit 6d606a040) and
--     the live page was re-probed OK, so every check I ran said "done";
--   * page_components.rendered_html — which is the ARTEFACT for a ported page,
--     not a cache of one — still held the broken copy, last written
--     2026-07-27 19:05. Any rebuild or re-assemble would have quietly restored
--     the fault, and the tool would have "un-repaired" itself with nobody
--     touching it.
--
-- WHAT CAUGHT IT: not a re-read of my own work. The new orphan_element_refs
-- check was run over the live DB as a precision measurement, and listed
-- tool-insight-injector among the ten broken pages — a tool I had "fixed"
-- hours earlier. A detector written for other tools found a defect in my own
-- repair. That is the argument for building the detector before the repairs,
-- and it is why the per-tool loop now ends at the DATABASE, not at the repo.
--
-- The HTML travels as base64 and is decoded in Postgres. Deliberate: the
-- section carries quotes, backslashes and JS template literals, and hand
-- dollar-quoting 9KB of that is exactly how a generator broke itself earlier in
-- this workstream. Base64 is alphanumerics — there is nothing in it to escape.
--
-- The payload was self-checked before this file was written: section tags
-- balanced, all six element ids present, and ZERO orphan references under the
-- same predicate the chassis check now applies.
--
-- content_data keeps its original port provenance (source URL + the sha256 of
-- the SOURCE page) untouched — that records where the page came from and is
-- still true. A `repair` key is added beside it, so the divergence from the
-- ported original is stated rather than silent.

\set ON_ERROR_STOP on

BEGIN;

CREATE TEMP TABLE t_repair(html text);
INSERT INTO t_repair(html)
VALUES (convert_from(decode('', 'base64'), 'UTF8'));

DO $pre$
DECLARE v_html text; v_rows int;
BEGIN
    SELECT html INTO v_html FROM t_repair;
    IF v_html IS NULL OR length(v_html) < 8000 THEN
        RAISE EXCEPTION 'payload did not decode to the expected section (length %)', length(v_html);
    END IF;
    IF position('id="biz-name"' in v_html) = 0 OR position('id="banned-tags"' in v_html) = 0 THEN
        RAISE EXCEPTION 'decoded payload is missing the restored input panel';
    END IF;

    SELECT count(*) INTO v_rows
      FROM page_components pc JOIN pages p ON p.id = pc.page_id JOIN sites s ON s.id = p.site_id
     WHERE s.domain = 'webdesign.co.uk' AND p.name = 'tool-insight-injector';
    IF v_rows <> 1 THEN
        RAISE EXCEPTION 'expected exactly 1 page_component for tool-insight-injector, found %', v_rows;
    END IF;
END $pre$;

UPDATE page_components pc
   SET rendered_html = (SELECT html FROM t_repair),
       content_data = pc.content_data || jsonb_build_object(
           'repair', jsonb_build_object(
               'at', to_char(NOW(), 'YYYY-MM-DD"T"HH24:MI:SSZ'),
               'by', 'webdesign tools repair, per-tool loop',
               'what', 'restored the input panel the port dropped; the surviving CSS and JS already specified every id and class',
               'diverges_from_source', true)),
       updated_at = NOW()
  FROM pages p, sites s
 WHERE pc.page_id = p.id AND p.site_id = s.id
   AND s.domain = 'webdesign.co.uk' AND p.name = 'tool-insight-injector';

DO $verify$
DECLARE v_html text;
BEGIN
    SELECT pc.rendered_html INTO v_html
      FROM page_components pc JOIN pages p ON p.id = pc.page_id JOIN sites s ON s.id = p.site_id
     WHERE s.domain = 'webdesign.co.uk' AND p.name = 'tool-insight-injector';

    IF position('id="biz-name"' in v_html) = 0 THEN
        RAISE EXCEPTION 'stored rendered_html still has no input panel';
    END IF;
    IF position('fill out the insights on the left' in v_html) > 0
       AND position('controls-panel' in v_html) = 0 THEN
        RAISE EXCEPTION 'copy still points at a panel that is not there';
    END IF;

    RAISE NOTICE 'insight-injector repaired at source: rendered_html now carries the input panel (% bytes)', length(v_html);
END $verify$;

COMMIT;
